    void* PImp;
    CCharString(const char* text, long length);   // 0x0099EBF0
    ~CCharString();                                // 0x0099EAE0
};
struct CDefinitionManager {
    long GetDefGlobalIndexFromName(const CCharString& name);   // 0x009AD410
